  /**
   * @method
   * @name gemini#createOrder
   * @description create a trade order
   * @see https://docs.gemini.com/rest-api/#new-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type must be 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(!isEqual(type, std::string("limit")))) {
                   throw ExchangeError(toString(
                       add(this->id,
                           std::string(
                               " createOrder() allows limit orders only"))));
                 }
                 std::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("client_order_id"));
                 params = this->omit(
                     params, ccxt::list{std::string("clientOrderId"),
                                        std::string("client_order_id")});
                 if (isTrue(isEqual(clientOrderId, std::any{}))) {
                   clientOrderId = toString(this->milliseconds());
                 }
                 std::any market = this->market(symbol);
                 std::any amountString =
                     this->amountToPrecision(symbol, amount);
                 std::any priceString = this->priceToPrecision(symbol, price);
                 std::any request = ccxt::dict{
                     {std::string("client_order_id"), clientOrderId},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("amount"), amountString},
                     {std::string("price"), priceString},
                     {std::string("side"), side},
                     {std::string("type"), std::string("exchange limit")},
                 };
                 type = this->safeString(params, std::string("type"), type);
                 params = this->omit(params, std::string("type"));
                 std::any triggerPrice = this->safeStringN(
                     params, ccxt::list{std::string("triggerPrice"),
                                        std::string("stop_price"),
                                        std::string("stopPrice")});
                 params =
                     this->omit(params, ccxt::list{std::string("triggerPrice"),
                                                   std::string("stop_price"),
                                                   std::string("stopPrice"),
                                                   std::string("type")});
                 if (isTrue(isEqual(type, std::string("stopLimit")))) {
                   throw ArgumentsRequired(toString(add(
                       add(add(this->id,
                               std::string(
                                   " createOrder() requires a triggerPrice "
                                   "parameter or a stop_price parameter for ")),
                           type),
                       std::string(" orders"))));
                 }
                 if (isTrue(!isEqual(triggerPrice, std::any{}))) {
                   ::setValue(request, std::string("stop_price"),
                              this->priceToPrecision(symbol, triggerPrice));
                   ::setValue(request, std::string("type"),
                              std::string("exchange stop limit"));
                 } else {
                   // No options can be applied to stop-limit orders at this
                   // time.
                   std::any timeInForce =
                       this->safeString(params, std::string("timeInForce"));
                   params = this->omit(params, std::string("timeInForce"));
                   if (isTrue(!isEqual(timeInForce, std::any{}))) {
                     if (isTrue(isTrue((isEqual(timeInForce,
                                                std::string("IOC")))) ||
                                isTrue((isEqual(
                                    timeInForce,
                                    std::string("immediate-or-cancel")))))) {
                       ::setValue(
                           request, std::string("options"),
                           ccxt::list{std::string("immediate-or-cancel")});
                     } else if (isTrue(isTrue((isEqual(timeInForce,
                                                       std::string("FOK")))) ||
                                       isTrue((isEqual(
                                           timeInForce,
                                           std::string("fill-or-kill")))))) {
                       ::setValue(request, std::string("options"),
                                  ccxt::list{std::string("fill-or-kill")});
                     } else if (isTrue(
                                    isEqual(timeInForce, std::string("PO")))) {
                       ::setValue(request, std::string("options"),
                                  ccxt::list{std::string("maker-or-cancel")});
                     }
                   }
                   std::any postOnly =
                       this->safeBool(params, std::string("postOnly"), false);
                   params = this->omit(params, std::string("postOnly"));
                   if (isTrue(isEqual(postOnly, true))) {
                     ::setValue(request, std::string("options"),
                                ccxt::list{std::string("maker-or-cancel")});
                   }
                   // allowing override for auction-only and
                   // indication-of-interest order options
                   std::any options =
                       this->safeString(params, std::string("options"));
                   if (isTrue(!isEqual(options, std::any{}))) {
                     ::setValue(request, std::string("options"),
                                ccxt::list{options});
                   }
                 }
                 std::any response = awaitValue(this->privatePostV1OrderNew(
                     this->extend(request, params)));
                 //
                 //      {
                 //          "order_id":"106027397702",
                 //          "id":"106027397702",
                 //          "symbol":"etheur",
                 //          "exchange":"gemini",
                 //          "avg_execution_price":"2877.48",
                 //          "side":"sell",
                 //          "type":"exchange limit",
                 //          "timestamp":"1650398122",
                 //          "timestampms":1650398122308,
                 //          "is_live":false,
                 //          "is_cancelled":false,
                 //          "is_hidden":false,
                 //          "was_forced":false,
                 //          "executed_amount":"0.014434",
                 //          "client_order_id":"1650398121695",
                 //          "options":[],
                 //          "price":"2800.00",
                 //          "original_amount":"0.014434",
                 //          "remaining_amount":"0"
                 //      }
                 //
                 return this->parseOrder(response);
               })
        .share();
  }

