  /**
   * @method
   * @name gemini#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://docs.gemini.com/rest-api/#get-past-trades
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit_trades"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("timestamp"),
                              this->parseToInt(divide(since, 1000)));
                 }
                 std::any response = awaitValue(this->privatePostV1Mytrades(
                     this->extend(request, params)));
                 return this->parseTrades(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name gemini#withdraw
   * @description make a withdrawal
   * @see https://docs.gemini.com/rest-api/#withdraw-crypto-funds
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} tag
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any>
  withdraw(std::any code, std::any amount, std::any address,
           std::any tag = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any tagparamsVariable =
                     this->handleWithdrawTagAndParams(tag, params);
                 tag = ::getValue(tagparamsVariable, 0);
                 params = ::getValue(tagparamsVariable, 1);
                 this->checkAddress(address);
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("amount"), amount},
                     {std::string("address"), address},
                 };
                 std::any response =
                     awaitValue(this->privatePostV1WithdrawCurrency(
                         this->extend(request, params)));
                 //
                 //   for BTC
                 //     {
                 //         "address":"mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR",
                 //         "amount":"1",
                 //         "withdrawalId":"02176a83-a6b1-4202-9b85-1c1c92dd25c4",
                 //         "message":"You have requested a transfer of 1 BTC to
                 //         mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR. This withdrawal
                 //         will be sent to the blockchain within the next 60
                 //         seconds."
                 //     }
                 //
                 //   for ETH
                 //     {
                 //         "address":"0xA63123350Acc8F5ee1b1fBd1A6717135e82dBd28",
                 //         "amount":"2.34567",
                 //         "txHash":"0x28267179f92926d85c5516bqc063b2631935573d8915258e95d9572eedcc8cc"
                 //     }
                 //
                 //   for error (other variations of error messages are also
                 //   expected)
                 //     {
                 //         "result":"error",
                 //         "reason":"CryptoAddressWhitelistsNotEnabled",
                 //         "message":"Cryptocurrency withdrawal address
                 //         whitelists are not enabled for account 24. Please
                 //         contact support@gemini.com for information on
                 //         setting up a withdrawal address whitelist."
                 //     }
                 //
                 std::any result =
                     this->safeString(response, std::string("result"));
                 if (isTrue(isEqual(result, std::string("error")))) {
                   throw ExchangeError(toString(
                       add(add(this->id, std::string(" withdraw() failed: ")),
                           this->json(response))));
                 }
                 return this->parseTransaction(response, currency);
               })
        .share();
  }

  std::any nonce() override {
    std::any nonceMethod = this->safeString(this->options, std::string("nonce"),
                                            std::string("milliseconds"));
    if (isTrue(isEqual(nonceMethod, std::string("milliseconds")))) {
      return this->milliseconds();
    }
    return this->seconds();
  }

  /**
   * @method
   * @name gemini#fetchDepositsWithdrawals
   * @description fetch history of deposits and withdrawals
   * @see https://docs.gemini.com/rest-api/#transfers
   * @param {string} [code] unified currency code for the currency of the
   * deposit/withdrawals, default is undefined
   * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal,
   * default is undefined
   * @param {int} [limit] max number of deposit/withdrawals to return, default
   * is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<std::any> fetchDepositsWithdrawals(
      std::any code = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit_transfers"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("timestamp"), since);
                 }
                 std::any response = awaitValue(this->privatePostV1Transfers(
                     this->extend(request, params)));
                 return this->parseTransactions(response);
               })
        .share();
  }

  std::any parseTransaction(std::any transaction,
                            std::any currency = std::any{},
                            std::any p2 = std::any{},
                            std::any p3 = std::any{}) override {
    //
    // withdraw
    //
    //   for BTC
    //     {
    //         "address":"mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR",
    //         "amount":"1",
    //         "withdrawalId":"02176a83-a6b1-4202-9b85-1c1c92dd25c4",
    //         "message":"You have requested a transfer of 1 BTC to
    //         mi98Z9brJ3TgaKsmvXatuRahbFRUFKRUdR. This withdrawal will be sent
    //         to the blockchain within the next 60 seconds."
    //     }
    //
    //   for ETH
    //     {
    //         "address":"0xA63123350Acc8F5ee1b1fBd1A6717135e82dBd28",
    //         "amount":"2.34567",
    //         "txHash":"0x28267179f92926d85c5516bqc063b2631935573d8915258e95d9572eedcc8cc"
    //     }
    //
    std::any timestamp =
        this->safeInteger(transaction, std::string("timestampms"));
    std::any currencyId =
        this->safeString(transaction, std::string("currency"));
    std::any code = this->safeCurrencyCode(currencyId, currency);
    std::any address =
        this->safeString(transaction, std::string("destination"));
    std::any type = this->safeStringLower(transaction, std::string("type"));
    // if status field is available, then it's complete
    std::any statusRaw = this->safeString(transaction, std::string("status"));
    std::any fee = std::any{};
    std::any feeAmount =
        this->safeNumber(transaction, std::string("feeAmount"));
    if (isTrue(!isEqual(feeAmount, std::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeAmount},
          {std::string("currency"), code},
      };
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"), this->safeString2(transaction, std::string("eid"),
                                              std::string("withdrawalId"))},
        {std::string("txid"),
         this->safeString(transaction, std::string("txHash"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"), std::any{}},
        {std::string("address"), address},
        {std::string("addressTo"), std::any{}},
        {std::string("addressFrom"), std::any{}},
        {std::string("tag"), std::any{}},
        {std::string("tagTo"), std::any{}},
        {std::string("tagFrom"), std::any{}},
        {std::string("type"), type},
        {std::string("amount"),
         this->safeNumber(transaction, std::string("amount"))},
        {std::string("currency"), code},
        {std::string("status"), this->parseTransactionStatus(statusRaw)},
        {std::string("updated"), std::any{}},
        {std::string("internal"), std::any{}},
        {std::string("comment"),
         this->safeString(transaction, std::string("message"))},
        {std::string("fee"), fee},
    };
  }

  virtual std::any parseTransactionStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("Advanced"), std::string("ok")},
        {std::string("Complete"), std::string("ok")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseDepositAddress(std::any depositAddress,
                               std::any currency = std::any{}) override {
    //
    //      {
    //          "address": "0xed6494Fe7c1E56d1bd6136e89268C51E32d9708B",
    //          "timestamp": "1636813923098",
    //          "addressVersion": "eV1" }
    //      }
    //
    std::any address = this->safeString(depositAddress, std::string("address"));
    std::any code = this->safeCurrencyCode(std::any{}, currency);
    return ccxt::dict{
        {std::string("currency"), code},
        {std::string("network"), std::any{}},
        {std::string("address"), address},
        {std::string("tag"), std::any{}},
        {std::string("info"), depositAddress},
    };
  }

  /**
   * @method
   * @name gemini#fetchDepositAddress
   * @see https://docs.gemini.com/rest-api/#get-deposit-addresses
   * @description fetch the deposit address for a currency associated with this
   * account
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the endpoint
   * @param {string} [params.network]  *required* The chain of currency
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any groupedByNetwork = awaitValue(
                            this->fetchDepositAddressesByNetwork(code, params));
                        std::any networkCode = std::any{};
                        std::any networkCodeparamsVariable =
                            this->handleNetworkCodeAndParams(params);
                        networkCode = ::getValue(networkCodeparamsVariable, 0);
                        params = ::getValue(networkCodeparamsVariable, 1);
                        std::any networkGroup = this->indexBy(
                            this->safeValue(groupedByNetwork, networkCode),
                            std::string("currency"));
                        return this->safeValue(networkGroup, code);
                      })
        .share();
  }

  /**
   * @method
   * @name gemini#fetchDepositAddressesByNetwork
   * @description fetch a dictionary of addresses for a currency, indexed by
   * network
   * @see https://docs.gemini.com/rest-api/#get-deposit-addresses
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network]  *required* The chain of currency
   * @returns {object} a dictionary of [address structures]{@link
   * https://docs.ccxt.com/?id=address-structure} indexed by the network
   */
  std::shared_future<std::any>
  fetchDepositAddressesByNetwork(std::any code,
                                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 code = ::getValue(currency, std::string("code"));
                 std::any networkCode = std::any{};
                 std::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(isEqual(networkCode, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchDepositAddresses() "
                                             "requires a network parameter"))));
                 }
                 std::any networkId = this->networkCodeToId(
                     networkCode, ::getValue(currency, std::string("code")));
                 std::any request = ccxt::dict{
                     {std::string("network"), networkId},
                 };
                 std::any response =
                     awaitValue(this->privatePostV1AddressesNetwork(
                         this->extend(request, params)));
                 std::any results = this->parseDepositAddresses(
                     response, ccxt::list{code}, false,
                     ccxt::dict{
                         {std::string("network"), networkCode},
                         {std::string("currency"), code},
                     });
                 return this->groupBy(results, std::string("network"));
               })
        .share();
  }

  std::any sign(std::any path, std::any api = std::string("public"),
                std::any method = std::string("GET"),
                std::any params = ccxt::dict{}, std::any headers = std::any{},
                std::any body = std::any{}) override {
    std::any url = add(std::string("/"), this->implodeParams(path, params));
    std::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      std::any apiKey = this->apiKey;
      if (isTrue(isLessThan(getIndexOf(apiKey, std::string("account")), 0))) {
        throw AuthenticationError(toString(
            add(this->id, std::string(" sign() requires an account-key, "
                                      "master-keys are not-supported"))));
      }
      std::any nonce = toString(this->nonce());
      std::any finalUrl = url;
      std::any request = this->extend(
          ccxt::dict{
              {std::string("request"), finalUrl},
              {std::string("nonce"), nonce},
          },
          query);
      std::any payload = this->json(request);
      payload = this->stringToBase64(payload);
      std::any signature =
          this->hmac(this->encode(payload), this->encode(this->secret), sha384);
      headers = ccxt::dict{
          {std::string("Content-Type"), std::string("text/plain")},
          {std::string("X-GEMINI-APIKEY"), this->apiKey},
          {std::string("X-GEMINI-PAYLOAD"), payload},
          {std::string("X-GEMINI-SIGNATURE"), signature},
      };
    } else {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    }
    url = add(::getValue(::getValue(this->urls, std::string("api")), api), url);
    if (isTrue(isTrue((isEqual(method, std::string("POST")))) ||
               isTrue((isEqual(method, std::string("DELETE")))))) {
      body = this->json(query);
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  std::any handleErrors(std::any httpCode, std::any reason, std::any url,
                        std::any method, std::any headers, std::any body,
                        std::any response, std::any requestHeaders,
                        std::any requestBody) override {
    if (isTrue(isEqual(response, std::any{}))) {
      if (isTrue(isString(body))) {
        std::any feedback = add(add(this->id, std::string(" ")), body);
        this->throwBroadlyMatchedException(
            ::getValue(this->exceptions, std::string("broad")), body, feedback);
      }
      return std::any{}; // fallback to default error handler
    }
    //
    //     {
    //         "result": "error",
    //         "reason": "BadNonce",
    //         "message": "Out-of-sequence nonce <1234> precedes previously used
    //         nonce <2345>"
    //     }
    //
    std::any result = this->safeString(response, std::string("result"));
    if (isTrue(isEqual(result, std::string("error")))) {
      std::any reasonInner = this->safeString(response, std::string("reason"));
      std::any message = this->safeString(response, std::string("message"));
      std::any feedback = add(add(this->id, std::string(" ")), message);
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), reasonInner,
          feedback);
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), message,
          feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), message,
          feedback);
      throw ExchangeError(toString(feedback));
    }
    return std::any{};
  }

  /**
   * @method
   * @name gemini#createDepositAddress
   * @description create a currency deposit address
   * @see https://docs.gemini.com/rest-api/#new-deposit-address
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  createDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any request = ccxt::dict{
                            {std::string("currency"),
                             ::getValue(currency, std::string("id"))},
                        };
                        std::any response = awaitValue(
                            this->privatePostV1DepositCurrencyNewAddress(
                                this->extend(request, params)));
                        std::any address =
                            this->safeString(response, std::string("address"));
                        this->checkAddress(address);
                        return ccxt::dict{
                            {std::string("currency"), code},
                            {std::string("address"), address},
                            {std::string("tag"), std::any{}},
                            {std::string("network"), std::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

  /**
   * @method
   * @name gemini#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://docs.gemini.com/rest-api/#candles
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any timeframeId = this->safeString(
                            this->timeframes, timeframe, timeframe);
                        std::any request = ccxt::dict{
                            {std::string("timeframe"), timeframeId},
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any response =
                            awaitValue(this->publicGetV2CandlesSymbolTimeframe(
                                this->extend(request, params)));
                        //
                        //     [
                        //         [1591515000000,0.02509,0.02509,0.02509,0.02509,0],
                        //         [1591514700000,0.02503,0.02509,0.02503,0.02509,44.6405],
                        //         [1591514400000,0.02503,0.02503,0.02503,0.02503,0],
                        //     ]
                        //
                        std::any candles = ccxt::list{};
                        if (isTrue(isArray(response))) {
                          candles = response;
                        }
                        return this->parseOHLCVs(candles, market, timeframe,
                                                 since, limit);
                      })
        .share();
  }

